event: response.output_text.done
data: {"type":"response.output_text.done","content_index":0,"item_id":"msg_08d0424ac6fb450a016ae36b91230487d1b74aa0afbbce7948","logprobs":[],"output_index":0,"sequence_number":555,"text":"<title>Coffee shop</title>\n<h1>Good morning</h1>\n<p>Northstar Coffee · Pickup in 8–12 min</p>\n<nav aria-label=\"Main navigation\">\n  <a href=\"#\" data-action=\"Coffee menu screen with espresso, cappuccino, and iced latte\">Menu</a> ·\n  <a href=\"#\" data-action=\"Orders screen showing recent coffee shop orders\">Orders</a> ·\n  <a href=\"#\" data-action=\"Profile screen for a coffee shop customer\">Profile</a>\n</nav>\n<h2>Popular today</h2>\n<article>\n  <h3>Oat milk cappuccino</h3>\n  <p>Double espresso, silky oat milk</p>\n  <p>$5.25</p>\n  <button data-action=\"Details screen for an oat milk cappuccino, with size and milk options\">Details</button>\n  <button data-action=\"Add oat milk cappuccino to a coffee shop order\">Add</button>\n</article>\n<article>\n  <h3>Vanilla cold brew</h3>\n  <p>Slow-steeped, house vanilla, served over ice</p>\n  <p>$4.75</p>\n  <button data-action=\"Details screen for a vanilla cold brew, with size and sweetness options\">Details</button>\n  <button data-action=\"Add vanilla cold brew to a coffee shop order\">Add</button>\n</article>\n<article>\n  <h3>Butter croissant</h3>\n  <p>Freshly baked this morning</p>\n  <p>$3.50</p>\n  <button data-action=\"Details screen for a butter croissant\">Details</button>\n  <button data-action=\"Add butter croissant to a coffee shop order\">Add</button>\n</article>\n<fieldset>\n  <legend>Your order</legend>\n  <label for=\"qty\">Oat milk cappuccino · $5.25</label>\n  <input id=\"qty\" type=\"number\" min=\"0\" value=\"1\">\n  <p>Subtotal: <strong id=\"total\">$5.25</strong></p>\n  <button data-action=\"Checkout screen for a coffee shop order with one oat milk cappuccino\">Checkout</button>\n  <button data-action=\"Edit order screen for a coffee shop order\">Edit order</button>\n</fieldset>\n<script>\nconst qty=document.querySelector('#qty'), total=document.querySelector('#total');\nqty.addEventListener('input',()=>{total.textContent='$'+(Math.max(0,Number(qty.value)||0)*5.25).toFixed(2)});\n</script>"}

